INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, realm_id) VALUES ('bc5a3cd8-aecf-4f84-8f5f-caf5d44dc5a5', 'user.expire.sms-viber.code', '300', null, 'user');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, realm_id) VALUES ('52b6892e-d950-45ff-843f-a564321545de', 'user.expire.incoming.call.code', '20', null, 'user');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, realm_id) VALUES ('95047368-931d-4b1b-82be-077c6eb10d6d', 'user.expire.incoming.call.email.code', '300', null, 'user');

update SETTINGS set NAME = 'Expire sms/ Viber code' where EXT_ID = 'user.expire.sms-viber.code';
update SETTINGS set NAME = 'Expire incomig call code' where EXT_ID = 'user.expire.incoming.call.code';
update SETTINGS set NAME = 'Expire incoming call email code' where EXT_ID = 'user.expire.incoming.call.email.code';
update SETTINGS set NAME = 'Inactive Block timeout' where EXT_ID = 'user.absence.blocking.days';
update SETTINGS set NAME = 'Inactive notification timeout' where EXT_ID = 'user.absence.notifications.days';

alter table ADMIN_EVENT_ENTITY change `REPRESENTATION` `REPRESENTATION` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
alter table SETTINGS change `DESC` `DESC` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
alter table SETTINGS change VALUE VALUE TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

update SETTINGS set UNIT = 'MINUTES' where EXT_ID = 'user.expire.sms-viber.code';
update SETTINGS set UNIT = 'SECONDS' where EXT_ID = 'user.expire.incoming.call.code';
update SETTINGS set UNIT = 'MINUTES' where EXT_ID = 'user.expire.incoming.call.email.code';
update SETTINGS set UNIT = 'DAYS' where EXT_ID = 'user.absence.blocking.days';
update SETTINGS set UNIT = 'DAYS' where EXT_ID = 'user.absence.notifications.days';

ALTER TABLE CUSTOMER CHANGE ID ID varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE USER_POST CHANGE TOMS_ID TOMS_ID varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
insert into CUSTOMER(ID, UPDATE_TIME) select distinct p.TOMS_ID, CURRENT_TIMESTAMP from USER_POST p;

